:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a3d;
  --text: #f0f0f5;
  --text-muted: #a0a0b8;
  --accent: #6c5ce7;
  --accent-hover: #7d6ff0;
  --accent-active: #5a4bd1;
  --focus-ring: #fdcb6e;
  --border-radius: 12px;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app {
  background: var(--card-bg);
  border-radius: var(--border-radius);
  box-shadow: var(--shadow);
  padding: 24px;
  width: 100%;
  max-width: 720px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header {
  text-align: center;
}

.app-header h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
  margin-top: 4px;
}

.palette {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
}

.swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  border-radius: var(--border-radius);
  overflow: hidden;
  background: rgba(255, 255, 255, 0.05);
  padding-bottom: 8px;
}

.swatch-color {
  width: 100%;
  aspect-ratio: 1 / 1;
  min-height: 80px;
  transition: background-color 0.2s ease;
}

.swatch-hex {
  font-family: 'SF Mono', 'Cascadia Code', 'Consolas', monospace;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
  letter-spacing: 0.02em;
}

.lock-btn {
  background: transparent;
  border: 2px solid var(--text-muted);
  border-radius: 50%;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-size: 1.1rem;
  color: var(--text-muted);
  transition: border-color 0.15s ease, color 0.15s ease, background-color 0.15s ease;
  flex-shrink: 0;
}

.lock-btn:hover {
  border-color: var(--text);
  color: var(--text);
}

.lock-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.lock-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.lock-btn[aria-pressed="true"]:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
}

.lock-btn[aria-pressed="true"]:active {
  background: var(--accent-active);
  border-color: var(--accent-active);
}

.controls {
  display: flex;
  justify-content: center;
}

.btn {
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 28px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.1s ease;
}

.btn-primary {
  background: var(--accent);
  color: #fff;
}

.btn-primary:hover {
  background: var(--accent-hover);
}

.btn-primary:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.btn-primary:active {
  background: var(--accent-active);
  transform: scale(0.97);
}

.app-footer {
  text-align: center;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 520px) {
  .palette {
    grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  }

  .app {
    padding: 16px;
  }

  .app-header h1 {
    font-size: 1.5rem;
  }

  .swatch-hex {
    font-size: 0.75rem;
  }

  .lock-btn {
    width: 32px;
    height: 32px;
    font-size: 1rem;
  }
}

@media (max-width: 360px) {
  .palette {
    grid-template-columns: repeat(2, 1fr);
  }

  .app {
    padding: 12px;
  }

  .btn {
    width: 100%;
  }
}

(function () {
  'use strict';

  const paletteEl = document.getElementById('palette');
  const generateBtn = document.getElementById('generate-btn');
  const liveRegion = document.getElementById('live-region');

  const SWATCH_COUNT = 5;
  const state = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return '#' + f(0) + f(8) + f(4);
  }

  function generateHarmoniousPalette() {
    const baseHue = Math.random() * 360;
    const scheme = Math.random() < 0.5 ? 'analogous' : 'split';
    const offsets = scheme === 'analogous'
      ? [-30, -15, 0, 15, 30]
      : [0, 30, 150, 180, 210];
    const saturation = 55 + Math.random() * 30;
    const lightnessBase = 45 + Math.random() * 20;

    return offsets.map((offset, i) => {
      const hue = (baseHue + offset + 360) % 360;
      const lightness = Math.min(85, Math.max(25, lightnessBase + (i - 2) * 8));
      const hex = hslToHex(hue, saturation, lightness);
      return { hex, locked: false };
    });
  }

  function render() {
    paletteEl.innerHTML = '';
    state.forEach((swatch, index) => {
      const wrapper = document.createElement('div');
      wrapper.className = 'swatch';

      const colorDiv = document.createElement('div');
      colorDiv.className = 'swatch-color';
      colorDiv.style.backgroundColor = swatch.hex;
      colorDiv.setAttribute('aria-hidden', 'true');

      const hexLabel = document.createElement('span');
      hexLabel.className = 'swatch-hex';
      hexLabel.textContent = swatch.hex.toUpperCase();
      hexLabel.setAttribute('aria-label', 'Color ' + (index + 1) + ': ' + swatch.hex.toUpperCase());

      const lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.setAttribute('aria-pressed', String(swatch.locked));
      lockBtn.setAttribute('aria-label', (swatch.locked ? 'Unlock' : 'Lock') + ' color ' + (index + 1) + ' ' + swatch.hex.toUpperCase());
      lockBtn.textContent = swatch.locked ? '\u{1F512}' : '\u{1F513}';

      lockBtn.addEventListener('click', () => {
        state[index].locked = !state[index].locked;
        render();
        announce('Color ' + (index + 1) + ' ' + (state[index].locked ? 'locked' : 'unlocked'));
      });

      wrapper.appendChild(colorDiv);
      wrapper.appendChild(hexLabel);
      wrapper.appendChild(lockBtn);
      paletteEl.appendChild(wrapper);
    });
  }

  function announce(message) {
    liveRegion.textContent = message;
  }

  function generate() {
    const fresh = generateHarmoniousPalette();
    for (let i = 0; i < SWATCH_COUNT; i++) {
      if (!state[i] || !state[i].locked) {
        state[i] = fresh[i];
      }
    }
    render();
    announce('New palette generated: ' + state.map((s) => s.hex.toUpperCase()).join(', '));
  }

  generateBtn.addEventListener('click', generate);

  // Initialize with a generated palette
  state.push(...generateHarmoniousPalette());
  render();
  announce('Palette ready: ' + state.map((s) => s.hex.toUpperCase()).join(', '));
})();
